(function(root){'use strict';
const H=typeof module==='object'?require('./engine'):root.Horar;
const topics={1:['Сам человек','Как изменится положение этого человека?','Уточните, чей именно вопрос разбирается.'],7:['Отношения и договорённости','Состоится ли наша встреча до конца недели?','Уточните, о каком человеке или соглашении идёт речь. Карта не сообщает чужие мысли.'],10:['Работа и должность','Получу ли я эту должность?','Отделяйте получение должности от ежедневных рабочих задач и размера зарплаты.'],2:['Мои деньги и вещи','Вернётся ли ко мне потерянная вещь?','Один вопрос должен касаться одной вещи или конкретной суммы.'],4:['Дом и недвижимость','Получится ли купить выбранную квартиру?','Укажите, о каком объекте или жилищной ситуации вы спрашиваете.'],5:['Дети и творчество','Удастся ли завершить этот творческий проект?','Опишите конкретный проект или событие. Медицинские вопросы требуют врача.'],3:['Короткая поездка и обучение','Состоится ли поездка в соседний город?','Речь о коротких поездках и начальном обучении; вуз и дальняя поездка вынесены отдельно.'],6:['Повседневная работа','Получится ли закончить текущую рабочую задачу?','Здесь повседневные обязанности. Получение должности смотрите в теме «Работа и должность».'],8:['Деньги партнёра','Получит ли партнёр ожидаемую выплату?','Отличайте собственные деньги от средств другого человека.'],9:['Дальняя поездка и вуз','Состоится ли моя поездка за границу?','Выберите одно событие: поездку, поступление или конкретный этап обучения.'],11:['Друзья и сообщество','Поддержит ли меня наша команда в этом проекте?','Уточните, какая именно помощь или совместная задача вас интересует.'],12:['Скрытые обстоятельства','Что в выбранной ситуации требует дополнительной проверки?','Эта широкая тема особенно сложна для автоматического разбора. Карта не устанавливает тайные факты.']};
function plainState(p){const a=[];if(p.dignity.includes('Обитель'))a.push('По используемым правилам этот участник символически находится в привычных условиях, где проще действовать самостоятельно.');if(p.dignity.includes('Экзальтация'))a.push('Правила отмечают усиленное положение: это поддерживающий знак внутри метода, но не подтверждение реальных преимуществ.');if(p.dignity.some(x=>x==='Изгнание'||x==='Падение'))a.push('Правила отмечают затруднённое положение. Его можно прочитать как зависимость от условий или нехватку свободы действий, а не как оценку человека.');if(!a.length)a.push('По четырём проверяемым положениям нет явного усиления или ослабления. Это нейтральный результат этой проверки, а не доказательство отсутствия ресурсов.');a.push(p.retro?'Видимое движение планеты обратное. В традиции это связывают с возвратом к старому вопросу, пересмотром решения или изменением планов. Само по себе это не означает, что кто-то обязательно вернётся.':'Видимое движение планеты прямое. Оно не добавляет отдельного признака пересмотра, но само по себе не обещает успеха.');return a;}
function explain(c){if(c.analysis){const R=typeof module==='object'?require('./reading'):root.HorarReading;return {title:c.verdict,summary:c.explanation,sections:R.explain(c).map(x=>({title:x.title,paragraphs:[x.fact,x.meaning,x.limit]}))};}const a=c.primary,same=c.querent===c.subject,q=c.planets[c.querent],s=c.planets[c.subject],topic=topics[c.input.target];let title,meaning;
 if(same){title='Однозначного ответа пока нет';meaning='Для вас и предмета вопроса правила выбрали одну и ту же планету. Обычное сравнение двух сторон здесь не работает: нельзя делать вывод, будто между ними уже есть связь, просто потому что показатель общий.';}
 else if(!a){title='Карта не даёт ясного ответа «да» или «нет»';meaning='Программа не нашла прямой связи между двумя главными показателями в пределах проверяемых углов. Это означает, что базовый способ получить ответ не сработал. Это результат старой базовой методики. Нажмите «Пересчитать расширенно по правилам 1.6», чтобы проверить непрямые связи на тех же исходных данных.';}
 else if(a.phase==='applying'){title=[90,180].includes(a.angle)?'Есть признак взаимодействия, но с трудностями':'Есть признак возможного взаимодействия';meaning=[90,180].includes(a.angle)?'Два главных показателя приближаются к связи, которую традиция связывает с напряжением или противоречиями. В рамках метода это повод рассмотреть препятствия, договорённости и компромиссы. Такой знак не равен отказу, но и не обещает положительный результат.':'Два главных показателя приближаются к определённому взаимному положению. В традиции это читают как возможность взаимодействия сторон. Это поддерживающий признак внутри метода, однако дальнейшее движение может измениться и событие не обязано произойти.';}
 else if(a.phase==='separating'){title='Найденная связь скорее относится к предыстории';meaning='Главные показатели сейчас удаляются от точного взаимного положения. В традиции такую картину связывают с тем, что уже началось или осталось позади. Программа не знает, было ли это разговором, встречей или отказом; подставлять конкретное событие без ваших фактов нельзя.';}
 else if(a.phase==='exact'){title='Показатели находятся в точной связи сейчас';meaning='Главные показатели образуют точное взаимное положение на выбранный момент. Метод выделяет этот момент как значимый для сравнения сторон. Но точность угла не говорит, чем закончится вопрос и произойдёт ли событие в эту минуту.';}
 else {title='Направление развития по этому признаку неясно';meaning='Взаимное движение главных показателей почти остановилось. По одной такой проверке нельзя надёжно назвать связь сближающейся или удаляющейся. Программа оставляет вывод открытым, вместо того чтобы придумывать определённость.';}
 const sections=[
 {title:'1. Что именно мы разбираем',paragraphs:[`Ваш вопрос: «${c.input.question}». Выбрана тема «${topic[0]}». Именно тема определяет, с какой стороной ситуации сравнивается ваш показатель.`,topic[2],'Текст вопроса сохраняется как контекст для вас. Программа не понимает его как человек и не определяет тему автоматически. Если выбранная тема не соответствует вопросу, расчёт может быть технически верным, но относиться не к тому, что вы имели в виду.']},
 {title:'2. Почему получился такой итог',paragraphs:[meaning,`Для вас выбран показатель «${q.name}», для предмета вопроса — «${s.name}». Это условные обозначения ролей, как две фишки на схеме. Они не говорят, что вы похожи на планету или что небесное тело заставляет человека поступать определённым образом.`,a?`В расчёте эта связь называется «${a.name.toLowerCase()}». Проверяется взаимное положение планет и направление его изменения, а не вероятность события в процентах.`:'Отсутствие прямой связи нельзя автоматически переводить в «ничего не получится». Для более полного традиционного суждения потребовались бы дополнительные правила.']},
 {title:'3. Что сказано о вашей стороне',paragraphs:plainState(q)},
 {title:'4. Что сказано о второй стороне или цели',paragraphs:same?['Для обеих ролей получился один показатель. Поэтому мы не считаем его дважды и не выдаём повтор одного факта за два независимых подтверждения.',...plainState(s)]:plainState(s)},
 {title:'5. Есть ли дополнительные признаки поддержки',paragraphs:[same?'Отдельно сравнить расположение двух разных показателей нельзя: они совпали.':c.receptions.length?'Найдены дополнительные отношения между положениями планет. В традиции их используют для уточнения того, как стороны символически соотносятся между собой. Это дополнительная деталь, которую нужно читать вместе с главным итогом.':'Дополнительная поддержка по двум проверяемым правилам не обнаружена. Это лишь отсутствие конкретного признака в карте. Оно не означает отсутствия чувств, доброй воли или реальной помощи.','Даже найденная поддержка не подтверждает любовь, честность, согласие на сделку или намерение другого человека. Такие вещи проверяются общением и поступками, а не положением планет.']},
 {title:'6. Что добавляет движение Луны',paragraphs:[c.lunar?.void?'До перехода в следующий знак Луна не образует ни одной из проверяемых точных связей. В этой методике это отдельный признак неопределённости развития; он не отменяет остальные показатели и не означает автоматическое «нет».':c.lunar?`До перехода в следующий знак найдено точных связей Луны: ${c.lunar.events.length}. Они показывают последовательность астрономических положений, которую традиция использует как дополнительный сюжет карты.`:'Дополнительный расчёт Луны ещё не готов. Главный итог выше основан на двух основных показателях; неизвестный результат этой проверки не считается отрицательным.',c.querent===1||c.subject===1?'Луна уже представляет одну из сторон вопроса, поэтому её положение не считается ещё одним независимым доводом.':'Здесь Луна используется как дополнительный показатель хода вопроса, а не как отдельный гарантированный прогноз.','Время точной связи планет — не назначенная дата вашей встречи, выплаты или поездки. Переводить градусы в дни автоматически приложение не пытается.']},
 {title:'7. Насколько полный этот разбор',paragraphs:[c.notices.length?`Расчёт отметил ${c.notices.length} дополнительных предостережений внутри традиционной методики. Их точные значения доступны во вкладке «Для профи». Они означают необходимость осторожной интерпретации, а не предсказание неприятностей.`:'Базовые проверки не выделили дополнительных предостережений. Это не делает прогноз гарантированным: отсутствие предупреждения не является доказательством точности.', 'Программа рассчитывает положения планет, сравнивает две главные роли и применяет ограниченный набор традиционных правил. Она пока не проверяет все способы связи, все препятствия и все изменения движения до завершения события. Поэтому честный итог иногда остаётся неопределённым.','Астрономические координаты можно проверить. Символический вывод об обычной жизни не является научно подтверждённым прогнозом. Используйте его для размышления, а реальные решения сверяйте с фактами.']},
 {title:'8. Что делать с этим результатом',paragraphs:['Сначала проверьте вопрос, тему, место и время: ошибка в исходных данных меняет карту. Затем перечитайте главный итог вместе с объяснением, а не только одну понравившуюся фразу.','Сохраните разбор в журнал. Когда ситуация прояснится, запишите, что произошло на самом деле. Так можно сравнить первоначальный текст с исходом, не переписывая его задним числом.','Для обсуждения нажмите «Поделиться результатом». Ссылка содержит вопрос и данные карты; любой получивший её сможет их прочитать. Для самостоятельного чтения без сайта скачайте PDF.']}
 ];return {title,summary:meaning,sections};}
const api={topics,explain};if(typeof module==='object')module.exports=api;else root.HorarSimple=api;
})(typeof globalThis!=='undefined'?globalThis:this);
